package cc.joycreator.joybrush.core.fill

/**
 * THE GOLDEN TABLE for [MaskPaint.pixel] — 4635 rows, and NOT written by hand.
 *
 * Generated 2026-09-29 by a SECOND, INDEPENDENT implementation of the three composites
 * (`fractions.Fraction` — exact rational arithmetic, never binary floating point), written from
 * JB-2.07a Decision 1 as the W3C defines it: source-over `(1-as)Cb + as Cs`, destination-out
 * `Cb(1-as)` on all four channels, destination-over `Cb + (1-ab)Cs`. The rounding was exact
 * round-half-up on the rational, applied once per channel.
 *
 * WHY A TABLE AND NOT MORE ASSERTIONS, which is the verification discipline of this task: a
 * hand-derived expected value agrees with the bug that produced it, because both come from the
 * same head. A table produced by a model that never saw the Kotlin's source cannot. It agreed
 * with [MaskPaint] on all 4635 rows, which is evidence that the Double pipeline loses nothing at a
 * rounding boundary; it is kept because the NEXT change to these formulas is exactly the change
 * it will catch. IT HAS ALREADY CAUGHT ONE: the BEHIND room was originally `1 - da/255`, which
 * evaluates a hair BELOW the exact (255-da)/255 in binary floating point, and 255 * 0.5 * room
 * then lands at 0.4999999999999982 and rounds down where the exact answer is 0.5 and rounds up.
 * The near-boundary block below is the pin for that.
 *
 * WHAT IS IN IT, in four kinds of block: the structured grid (every mode against a spread of
 * colours, opacities, coverages and premultiplied destinations — empty, half and opaque paper);
 * destinations that are NOT premultiplied, which is the only thing that pins the colour <= alpha
 * clamp (a no-op on well-formed input, and the reason a corrupt tile cannot become a white halo
 * on export); a NEAR-BOUNDARY block that lands products on a .5 rounding boundary for both
 * plausible algebraic arrangements of each formula; and a random sweep off the grid.
 *
 * WHY IT IS SPLIT INTO 6 CLASSES. Every row is built inside a static initialiser, and the JVM
 * refuses a method larger than 64 KB of bytecode — one `val ROWS = listOf(...)` of this size
 * does not compile. The parts carry no meaning beyond that, which is why [MaskPaintGoldenRow]
 * is top level and a row never learns which part it landed in.
 *
 * The generator itself is not committed, because a committed generator nothing can re-run is a
 * table with a comment attached; its source and the exact command are in the Questions section of
 * `tasks/joybrush/specs/JB-2.07a_lasso_fill.md`.
 */
internal object MaskPaintGolden {

    /** The whole table, in the order it was generated. */
    val ROWS: List<MaskPaintGoldenRow> = ArrayList<MaskPaintGoldenRow>(4641).apply {
        addAll(MaskPaintGoldenPart1.ROWS)
        addAll(MaskPaintGoldenPart2.ROWS)
        addAll(MaskPaintGoldenPart3.ROWS)
        addAll(MaskPaintGoldenPart4.ROWS)
        addAll(MaskPaintGoldenPart5.ROWS)
        addAll(MaskPaintGoldenPart6.ROWS)
    }

    /** How many rows there must be for this to still be evidence. Asserted by the test. */
    const val EXPECTED_SIZE = 4635
}

/**
 * One row: the inputs, and what the exact-rational model says they produce.
 *
 * TOP LEVEL rather than nested in a part, because the parts are only a bytecode-size workaround
 * and a row has no business knowing which slice of the table it landed in.
 */
internal class MaskPaintGoldenRow(
    val mode: MaskPaintMode,
    val argb: Int,
    val opacity: Float,
    val coverage: Int,
    val dest: IntArray,
    val expect: IntArray,
)

